INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources)
SELECT '2c2c74d5-017d-4889-9fad-907f0f556271'::uuid, ct.id, s.reasoning, s.sources
FROM s JOIN inform.compass_topics ct ON ct.topic_key = s.topic_key AND ct.is_live = true
ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning = EXCLUDED.reasoning, sources = EXCLUDED.sources;

DO $$
DECLARE n INTEGER;
        v_ext BIGINT;
BEGIN
  -- Identity gate (WR-01): the hardcoded politician UUID must belong to the
  -- intended official's external_id — a wrong-but-existing UUID would satisfy
  -- the FK and the count gate below while silently misattributing stances.
  SELECT external_id INTO v_ext FROM essentials.politicians WHERE id = '2c2c74d5-017d-4889-9fad-907f0f556271';
  IF v_ext IS DISTINCT FROM -4174955 THEN
    RAISE EXCEPTION 'UUID 2c2c74d5-017d-4889-9fad-907f0f556271 does not belong to external_id -4174955 (Cyndy Hillier) — found %', v_ext;
  END IF;
  SELECT COUNT(*) INTO n FROM inform.politician_answers WHERE politician_id = '2c2c74d5-017d-4889-9fad-907f0f556271';
  IF n <> 10 THEN
    RAISE EXCEPTION 'Expected % answers, found % — topic_key mismatch dropped rows', 10, n;
  END IF;
  -- Context-parity gate (WR-03): the context VALUES list is a verbatim
  -- duplicate of the answers list; count it too so a single-sided edit
  -- cannot silently drop or skew reasoning/sources rows.
  SELECT COUNT(*) INTO n FROM inform.politician_context WHERE politician_id = '2c2c74d5-017d-4889-9fad-907f0f556271';
  IF n <> 10 THEN
    RAISE EXCEPTION 'Expected % context rows, found % — answers/context VALUES lists diverged', 10, n;
  END IF;
END $$;

COMMIT;
